  const cards = await page.locator('.shop-card').count();
  const names = await page.locator('.shop-card h3').allTextContents();
  await page.locator('#shopClose').click();
  await page.locator('#startBtn').click();
  await page.keyboard.press('d');
  await page.keyboard.press('j');
  await page.keyboard.press('k');
  await page.keyboard.press('Escape');
  const paused = await page.locator('#pauseBadge').evaluate(el => el.classList.contains('visible'));
  await page.keyboard.press('Escape');
  console.log(JSON.stringify({cards, names, paused, touchCount: await page.locator('.touch-controls [data-action]').count(), errors}));
  await page.setViewportSize({width:390,height:844});
  const touchVisible = await page.locator('#touchControls').isVisible();
  console.log(JSON.stringify({mobileTouchVisible: touchVisible, arenaHeight: await page.locator('#game').evaluate(el => Math.round(el.getBoundingClientRect().height))}));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
