function summon(type){const p=state.player;state.minions=state.minions.filter(m=>m.type!==type);const base={type,x:p.x+rand(-24,24),y:p.y,hp:70,maxHp:70,cool:rand(.2,.8),life:30,hit:0};if(type==='wolfA'||type==='wolfB'){base.hp=68;base.maxHp=68;base.life=0}if(type==='nue'){base.hp=84;base.maxHp=84;base.y=p.y-95;base.life=28}if(type==='frog'){base.hp=58;base.maxHp=58;base.life=16}if(type==='elephant'){base.hp=110;base.maxHp=110;base.life=30}state.minions.push(base);if(type==='wolfA'||type==='wolfB'){if(!state.minions.some(m=>m.type==='wolfA'))summon('wolfA');if(!state.minions.some(m=>m.type==='wolfB'))summon('wolfB')}emit(base.x,base.y-25,'#9c84c9',14,1);}
function castMegumi(){const sequence=['wolfA','nue','frog','elephant'],labels=['PERROS DIVINOS','NUE','SAPOS','ELEFANTE MÁXIMO'];let index=state.minions.length===0?0:state.inoCycle%sequence.length;const type=sequence[index];state.inoCycle=(index+1)%sequence.length;if(type==='wolfA'){summon('wolfA');summon('wolfB')}else summon(type);if(type==='frog'){for(const e of state.enemies.filter(e=>Math.abs(e.x-state.player.x)<W*.5)){e.bound=Math.max(e.bound||0,2.4);damageEnemy(e,12,0)}}floatText(state.player.x+state.player.face*48,state.player.y-92,'十種影法術','#c5a6ed');showToast(`${labels[index]} · ¡A luchar!`)}
function special(){const p=state.player,c=chars[state.active];if(!state.running||state.paused||p.special>0)return;if(p.energy<35){showToast('Energía maldita insuficiente');return}p.energy-=35;p.special=1.1;if(state.active==='megumi'){castMegumi();return}if(state.active==='ino'){const beast=['TORTUGA','DRAGÓN','NARVAL'][state.inoCycle%3];state.inoCycle=(state.inoCycle+1)%3;const reach=beast==='DRAGÓN'?W*.58:beast==='NARVAL'?W*.35:130;let hits=0;for(const e of state.enemies){const dx=e.x-p.x;if(Math.abs(dx)<reach&&(beast==='TORTUGA'||Math.sign(dx)===p.face)){damageEnemy(e,beast==='DRAGÓN'?45:beast==='NARVAL'?50:28,2);hits++}}if(beast==='TORTUGA'){p.invul=1.05;emit(p.x,p.y-25,'#a8d69c',26,1.1);showToast('REIKI · CAPARAZÓN PROTECTOR')}else if(beast==='DRAGÓN'){emit(p.x+p.face*90,p.y-42,'#e68b64',32,1.5);showToast('RYU · ALIENTO DEL DRAGÓN')}else{p.vx=p.face*590;emit(p.x+p.face*45,p.y-34,'#b7e5df',24,1.4);showToast('KIRIN · EMBESTIDA DEL NARVAL')}if(!hits&&beast!=='TORTUGA')showToast(`${beast} · ¡A punto!`);return}const radius=state.active==='nobara'?W*.52:W*.42;let count=0;for(const e of state.enemies){if(Math.abs(e.x-p.x)<radius){damageEnemy(e,state.active==='nobara'?36:29,2);count++}}if(state.active==='miwa'){p.invul=1.15;emit(p.x,p.y-25,'#a8c6df',32,1.3);showToast('DOMINIO SIMPLE · BARRERA DESPLEGADA')}else{emit(p.x+75*p.face,p.y-35,'#f6a17f',24,1.5);showToast('RESONANCIA · CLAVOS MALDITOS')}if(!count&&state.active!=='miwa')showToast(c.special+' · ¡LISTA!')}

