function removeMinion(m){const i=state.minions.indexOf(m);if(i<0)return;state.minions.splice(i,1);emit(m.x,m.y-25,'#9b85c1',12,.8);if(m.type==='wolfA'||m.type==='wolfB'){const partner=state.minions.find(a=>a.type==='wolfA'||a.type==='wolfB');if(partner){partner.type='total';partner.hp=Math.min(150,partner.hp+45);partner.maxHp=150;floatText(partner.x,partner.y-80,'渾','#f2d189');showToast('PERRO DIVINO TOTAL · ¡SE FUSIONAN!')}else showToast('El último Perro Divino cayó')}}
function updateMinions(dt){for(let i=state.minions.length-1;i>=0;i--){const m=state.minions[i];m.cool-=dt;m.hit=Math.max(0,(m.hit||0)-dt);if(m.life>0){m.life-=dt;if(m.life<=0){removeMinion(m);continue}}const target=state.enemies.reduce((best,e)=>!best||Math.abs(e.x-m.x)<Math.abs(best.x-m.x)?e:best,null);if(!target)continue;const dx=target.x-m.x,dist=Math.abs(dx);if(m.type==='nue'){m.y=state.player.y-105+Math.sin(performance.now()/260+i)*8}else if(m.type==='elephant'){m.x=clamp(state.player.x+state.player.face*90,35,W-35);m.y=state.player.y}else if(m.type==='frog'){m.x=clamp(state.player.x+state.player.face*55,35,W-35);m.y=state.player.y;if(m.cool<=0&&dist<300){target.bound=Math.max(target.bound||0,2);damageEnemy(target,11,0);m.cool=1.15}}else{m.x+=Math.sign(dx)*Math.min(Math.max(0,dist-48),130*dt);m.y=state.player.y}if(m.type==='elephant'&&m.cool<=0){state.projectiles.push({x:m.x+state.player.face*24,y:m.y-53,vx:state.player.face*360,life:1.6,damage:32,color:'#91d9e7'});m.cool=1.15}else if((m.type==='wolfA'||m.type==='wolfB'||m.type==='total'||m.type==='nue')&&m.cool<=0&&dist<(m.type==='nue'?280:78)){damageEnemy(target,m.type==='total'?29:m.type==='nue'?24:17,1);m.cool=m.type==='total'?.65:.9;emit(m.x,m.y-30,m.type==='nue'?'#9edbea':'#d7d2c8',5,.5)}}for(let i=state.projectiles.length-1;i>=0;i--){const b=state.projectiles[i];b.x+=b.vx*dt;b.life-=dt;const hit=state.enemies.find(e=>Math.abs(e.x-b.x)<22&&Math.abs(e.y-b.y)<60);if(hit){damageEnemy(hit,b.damage,1);emit(b.x,b.y,b.color,8,.7);state.projectiles.splice(i,1)}else if(b.life<=0||b.x<0||b.x>W)state.projectiles.splice(i,1)}}
