const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = targets.find(t => t.type === 'page');
if (!page) throw new Error('No Chrome page target');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let nextId = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const {resolve, reject} = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
  }
};
function call(method, params = {}) {
  const id = ++nextId;
  ws.send(JSON.stringify({id, method, params}));
  return new Promise((resolve, reject) => pending.set(id, {resolve, reject}));
}
async function evaluate(expression) {
  const result = await call('Runtime.evaluate', {expression, returnByValue: true, awaitPromise: true});
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
  return result.result.value;
}
await call('Runtime.enable');
await call('Page.enable');
const result = {};
result.initial = await evaluate(`({title:document.title, shopOpen:document.getElementById('shopModal').classList.contains('open'), touchDisplay:getComputedStyle(document.getElementById('touchControls')).display})`);
await evaluate(`document.querySelector('[data-open-shop]').click()`);
result.menuShopOpened = await evaluate(`document.getElementById('shopModal').classList.contains('open')`);
result.shopCardCount = await evaluate(`document.querySelectorAll('#shopCards .shop-card').length`);
await evaluate(`document.getElementById('shopClose').click()`);
await evaluate(`document.getElementById('startBtn').click()`);
result.started = await evaluate(`({hidden:document.getElementById('startOverlay').classList.contains('hidden'), wave:document.getElementById('waveNum').textContent, progress:document.getElementById('waveProgress').textContent})`);
const beforeEnergy = await evaluate(`document.getElementById('energyText').textContent`);
await evaluate(`window.dispatchEvent(new KeyboardEvent('keydown',{key:'k',bubbles:true}))`);
await new Promise(resolve => setTimeout(resolve, 120));
await evaluate(`window.dispatchEvent(new KeyboardEvent('keyup',{key:'k',bubbles:true}))`);
result.keyboardTechnique = {beforeEnergy, afterEnergy: await evaluate(`document.getElementById('energyText').textContent`)};
await evaluate(`document.querySelector('[data-action="attack"]').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1,pointerType:'touch'}))`);
await evaluate(`document.querySelector('[data-action="attack"]').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1,pointerType:'touch'}))`);
result.mobile = await (async()=>{
  await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
  return await evaluate(`({viewport:[innerWidth,innerHeight], touchDisplay:getComputedStyle(document.getElementById('touchControls')).display, bodyScroll:document.body.scrollHeight>innerHeight, arenaWidth:Math.round(document.getElementById('arenaWrap').getBoundingClientRect().width)})`);
})();
