const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = targets.find(t => t.type === 'page');
if (!page) throw new Error('No Chrome page target');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let nextId = 0;
const pending = new Map();
ws.onmessage = async event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const {resolve, reject} = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
    return;
  }
  if (msg.method === 'Fetch.requestPaused') {
    try {
      const bodyResult = await call('Fetch.getResponseBody', {requestId: msg.params.requestId});
      const source = bodyResult.base64Encoded ? atob(bodyResult.body) : bodyResult.body;
      const exposed = source.replace(/\}\)\(\);\s*$/, 'window.__gameTest={state,chars,startGame,finishGame,special,attack,switchChar,removeMinion,beginWave,updateCharacter,updateMinions};})();');
      if (exposed === source) throw new Error('Could not instrument game.js closure');
      await call('Fetch.fulfillRequest', {requestId: msg.params.requestId, responseCode: 200, responseHeaders: [{name:'Content-Type',value:'text/javascript; charset=utf-8'}], body: btoa(exposed)});
    } catch (error) {
      console.error('Interception failed:', error);
      await call('Fetch.continueRequest', {requestId: msg.params.requestId});
    }
  }
};
function call(method, params = {}) {
  const id = ++nextId;
  ws.send(JSON.stringify({id, method, params}));
  return new Promise((resolve, reject) => pending.set(id, {resolve, reject}));
}
async function evaluate(expression) {
  const result = await call('Runtime.evaluate', {expression, returnByValue: true, awaitPromise: true});
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description || result.exceptionDetails.text);
  return result.result.value;
}
await call('Runtime.enable');
await call('Page.enable');
await call('Fetch.enable', {patterns:[{urlPattern:'*game.js*', requestStage:'Response'}]});
await call('Page.reload', {ignoreCache:true});
for (let i=0;i<30;i++) {
  const ready = await evaluate(`!!window.__gameTest`).catch(()=>false);
  if (ready) break;
  await new Promise(resolve=>setTimeout(resolve,100));
}
if (!await evaluate(`!!window.__gameTest`)) throw new Error('Test instrumentation did not load');
const out = {};
out.menu = await evaluate(`({touch:getComputedStyle(document.getElementById('touchControls')).display, shopOpen:document.getElementById('shopModal').classList.contains('open')})`);
await evaluate(`document.querySelector('[data-open-shop]').click()`);
out.menuShop = await evaluate(`({open:document.getElementById('shopModal').classList.contains('open'), cards:document.querySelectorAll('#shopCards .shop-card').length})`);
await evaluate(`document.getElementById('shopClose').click(); __gameTest.startGame()`);
out.waveOne = await evaluate(`({wave:__gameTest.state.wave,count:__gameTest.state.waveCount,grade:document.getElementById('gradeName').textContent,touch:getComputedStyle(document.getElementById('touchControls')).display})`);
await evaluate(`__gameTest.state.wave=3;__gameTest.beginWave();__gameTest.updateCharacter()`);
out.waveThree = await evaluate(`({count:__gameTest.state.waveCount,grade:document.getElementById('gradeName').textContent})`);
await evaluate(`__gameTest.finishGame()`);
out.defeat = await evaluate(`({visible:!document.getElementById('startOverlay').classList.contains('hidden'),shopButton:!!document.querySelector('#startOverlay [data-open-shop]'),touch:getComputedStyle(document.getElementById('touchControls')).display})`);
await evaluate(`document.querySelector('#startOverlay [data-open-shop]').click()`);
out.defeatShop = await evaluate(`({open:document.getElementById('shopModal').classList.contains('open'),cards:document.querySelectorAll('#shopCards .shop-card').length})`);
await evaluate(`document.getElementById('shopClose').click();document.getElementById('startBtn').click()`);
out.retry = await evaluate(`({running:__gameTest.state.running,over:__gameTest.state.over,overlayHidden:document.getElementById('startOverlay').classList.contains('hidden'),touch:getComputedStyle(document.getElementById('touchControls')).display})`);
// Miwa's only special is the defensive Simple Domain; the basic is presented as the katana.
await evaluate(`__gameTest.switchChar('miwa');__gameTest.state.player.energy=100;__gameTest.special()`);
out.miwa = await evaluate(`({skill:document.getElementById('skillList').innerText,invul:__gameTest.state.player.invul,toast:document.getElementById('toast').textContent})`);
// Test each Megumi summon and the Divine Dog fusion, without waiting for combat timers.
await evaluate(`__gameTest.state.owned.push('megumi');__gameTest.switchChar('megumi');__gameTest.state.minions=[];__gameTest.state.megumiCycle=0;__gameTest.state.player.energy=100;__gameTest.state.player.special=0;__gameTest.special()`);
out.megumiDogs = await evaluate(`__gameTest.state.minions.map(m=>m.type)`);
await evaluate(`__gameTest.removeMinion(__gameTest.state.minions.find(m=>m.type==='wolfA'))`);
out.dogFusion = await evaluate(`({minions:__gameTest.state.minions.map(m=>m.type),toast:document.getElementById('toast').textContent})`);
const summonResults=[];
for (const expected of ['nue','frog','elephant']) {
  await evaluate(`__gameTest.state.player.energy=100;__gameTest.state.player.special=0;__gameTest.special()`);
  summonResults.push(await evaluate(`({expected:${JSON.stringify(expected)},minion:__gameTest.state.minions.at(-1)?.type,toast:document.getElementById('toast').textContent})`));
}
out.megumiCycle=summonResults;
// Ino's three abilities cycle in the agreed order.
await evaluate(`__gameTest.state.owned.push('ino');__gameTest.switchChar('ino');__gameTest.state.inoCycle=0`);
out.ino=[];
for(let i=0;i<3;i++){
  await evaluate(`__gameTest.state.player.energy=100;__gameTest.state.player.special=0;__gameTest.special()`);
  out.ino.push(await evaluate(`({toast:document.getElementById('toast').textContent,energy:document.getElementById('energyText').textContent})`));
}
// Confirm touch input invokes attack during combat.
await evaluate(`document.querySelector('[data-action="attack"]').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:7,pointerType:'touch'}))`);
out.touchAttack=await evaluate(`({attackTimer:__gameTest.state.player.attack,controls:getComputedStyle(document.getElementById('touchControls')).display})`);
await evaluate(`document.querySelector('[data-action="attack"]').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:7,pointerType:'touch'}))`);
console.log(JSON.stringify(out,null,2));
ws.close();

